/**
 * Warna status Request Pendaftaran Mokas — disamakan dengan indikator desk
 * (Style per state di workflow "Request Pendaftaran Mokas").
 */

const STATE_COLOR = {
	Draft: 'gray',
	'Menunggu Approval Pimcab': 'orange',
	'Menunggu Approval MO': 'blue',
	'Menunggu Approval Direktur': 'purple',
	Approved: 'green',
	Rejected: 'red',
}

const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	purple: 'bg-ui-surface-purple-100 text-ui-ink-purple-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}

const DOT = {
	gray: 'border-ui-line-gray-400',
	orange: 'border-ui-line-orange-500',
	blue: 'border-ui-line-blue-500',
	purple: 'border-ui-line-purple-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
}

export const STATUS_LIST = Object.keys(STATE_COLOR)

export function mokasPillClass(status) {
	return PILL[STATE_COLOR[status]] || PILL.gray
}

export function mokasDotClass(status) {
	return DOT[STATE_COLOR[status]] || DOT.gray
}

// Pesan konfirmasi sebelum aksi Workflow — sama dengan form desk.
export function pesanKonfirmasi(aksi, status) {
	if (aksi === 'Ajukan Approval')
		return 'Apakah Anda yakin ingin MENGAJUKAN request ini? Data dan dokumen tidak bisa diubah lagi setelah diajukan.'
	if (aksi === 'Approve')
		return status === 'Menunggu Approval Direktur'
			? 'Apakah Anda yakin ingin APPROVE request ini? Data Mokas akan otomatis dibuat.'
			: 'Apakah Anda yakin ingin APPROVE request ini?'
	if (aksi === 'Reject')
		return 'Apakah Anda yakin ingin REJECT request ini? Request yang ditolak tidak bisa diajukan ulang; pengaju harus membuat request baru.'
	return `Apakah Anda yakin ingin ${aksi}?`
}
